#!/usr/bin/env python3
"""
Check that every relative Markdown link in this repository points to a file that
actually exists. Skips absolute URLs (http/https), in-page anchors (#...), and links
to gitignored files (e.g. prometheus/prometheus.yml, litellm/litellm.env) that are
only generated by ./setup.sh - a fresh checkout (as used by CI) never has them, but
that's expected, not a broken link.

Used by the CI workflow (.github/workflows/ci.yml) and can be run locally:
    python3 .github/scripts/check_markdown_links.py
"""
import re
import subprocess
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent.parent
LINK_PATTERN = re.compile(r"\[[^\]]+\]\(([^)]+)\)")


def find_markdown_files(root: Path):
    for path in root.rglob("*.md"):
        if ".git" in path.parts or "node_modules" in path.parts or "build" in path.parts:
            continue
        yield path


def is_gitignored(path: Path, root: Path = REPO_ROOT) -> bool:
    """True if `path` is ignored by git (e.g. generated by ./setup.sh, never committed)."""
    result = subprocess.run(
        ["git", "check-ignore", "-q", str(path)],
        cwd=root,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    return result.returncode == 0


def find_broken_links(root: Path, ignored_check=None):
    """Return unresolved relative links from Markdown files below ``root``."""
    if ignored_check is None:
        ignored_check = lambda path: is_gitignored(path, root)
    broken = []
    for md_file in find_markdown_files(root):
        text = md_file.read_text(encoding="utf-8")
        base_dir = md_file.parent
        for link in LINK_PATTERN.findall(text):
            if link.startswith(("http://", "https://", "//", "#", "mailto:")):
                continue
            # Strip any in-page anchor suffix (e.g. "file.md#section")
            link_path = link.split("#", 1)[0]
            if not link_path:
                continue
            if link_path.startswith("@site/"):
                # Resolve Docusaurus @site alias relative to the site directory
                site_name = "architecture" if "architecture" in md_file.parts else "user"
                target = (root / f"docs/{site_name}" / link_path[6:]).resolve()
            elif link_path.startswith("/"):
                # Docusaurus root-relative link or static asset
                site_name = "architecture" if "architecture" in md_file.parts else "user"
                target = (root / f"docs/{site_name}/static" / link_path.lstrip("/")).resolve()
            else:
                target = (base_dir / link_path).resolve()
            if not target.exists() and not ignored_check(target):
                broken.append((str(md_file.relative_to(root)), link))
    return broken


def main() -> int:
    broken = find_broken_links(REPO_ROOT)

    if broken:
        print(f"Found {len(broken)} broken relative Markdown link(s):")
        for md_file, link in broken:
            print(f"  {md_file}: {link}")
        return 1

    print("All relative Markdown links resolve correctly.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
